"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9070],{3006:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"TrainShieldGuiController","desc":"Drives the diegetic `TrainShieldGui` SurfaceGui on each tagged\\n`TrainShieldMonitor` part. Discovers monitors via CollectionService, clones\\nthe `GuiAssets.TrainShieldGui` template onto each (client-locally, so every\\nplayer drives an independent copy on the shared surface), and updates two\\nreadouts on its CRT face each frame: the train shield (Online/Critical,\\neased toward `Signals.OnTrainShieldChanged` snapshots) and the train fuel\\nreserve (extrapolated from `Signals.OnTrainStateChanged`, mirroring the\\non-screen fuel HUD). Each monitor owns a Janitor that destroys its clone and\\ndisconnects its render loop when the tag is removed.","realm":["Client"],"source":{"line":17,"path":"src/StarterPlayer/StarterPlayerScripts/TrainShieldGuiController.client.luau"}}')}}]);